package com.mycompany.cotizacion;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.text.DecimalFormat;import com.toedter.calendar.JDateChooser;
public class jdlCotizacion extends JDialog {
 private final JTextField txtNumCotizacion=new JTextField(15),txtDescripcion=new JTextField(25),txtPrecio=new JTextField(12);
 private final JButton btnBuscar=new JButton("Buscar"),btnCancelar=new JButton("Cancelar"),btnCerrar=new JButton("Cerrar"),btnDeshabilitar=new JButton("Deshabilitar"),btnGuardar=new JButton("Guardar"),btnHabilitar=new JButton("Habilitar"),btnLimpiar=new JButton("Limpiar"),btnNuevo=new JButton("Nuevo");
 private final JComboBox<String> cmbStatus=new JComboBox<>(new String[]{"Activas","Inactivas"});
 private final JDateChooser jdcFecha=new JDateChooser();
 private final JLabel lblPagoInicial=new JLabel(),lblPagoMensual=new JLabel(),lblTotalFin=new JLabel();
 private final JRadioButton rdb12=new JRadioButton("12 meses"),rdb24=new JRadioButton("24 meses"),rdb36=new JRadioButton("36 meses"),rdb48=new JRadioButton("48 meses");
 private final JSpinner spnPorcentaje=new JSpinner(new SpinnerNumberModel(0,0,100,1));
 private final JTable tbDatos=new JTable(new DefaultTableModel(new String[]{"Número","Descripción","Precio","Plazo"},0));
 private final DecimalFormat formato=new DecimalFormat("$ #,##0.00");private final CotizacionDb db=new CotizacionDb();
 public jdlCotizacion(Frame padre,boolean modal){super(padre,"Cotización",modal);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);setSize(790,470);setLocationRelativeTo(padre);initComponents();limpiar();deshabilitar();addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosing(java.awt.event.WindowEvent e){cerrarVentana();}});}
 private void initComponents(){JPanel base=new JPanel(new BorderLayout(12,12));base.setBorder(BorderFactory.createEmptyBorder(15,15,15,15));setContentPane(base);JPanel datos=new JPanel(new GridLayout(5,2,8,5));JPanel numero=new JPanel(new FlowLayout(FlowLayout.LEFT,0,0));numero.add(txtNumCotizacion);numero.add(btnBuscar);datos.add(new JLabel("Num. Cotización"));datos.add(numero);datos.add(new JLabel("Descripción"));datos.add(txtDescripcion);datos.add(new JLabel("Porcentaje"));datos.add(spnPorcentaje);datos.add(new JLabel("Precio"));datos.add(txtPrecio);JPanel plazos=new JPanel(new FlowLayout(FlowLayout.LEFT,0,0));ButtonGroup grupo=new ButtonGroup();for(JRadioButton r:new JRadioButton[]{rdb12,rdb24,rdb36,rdb48}){grupo.add(r);plazos.add(r);r.addActionListener(e->calcular());}datos.add(new JLabel("Plazos"));datos.add(plazos);JPanel lateral=new JPanel(new GridLayout(6,1,4,5));lateral.add(new JLabel("Fecha"));jdcFecha.setDateFormatString("dd/MM/yyyy");lateral.add(jdcFecha);for(JButton b:new JButton[]{btnNuevo,btnGuardar,btnDeshabilitar,btnHabilitar})lateral.add(b);JPanel arriba=new JPanel(new BorderLayout(12,0));arriba.add(datos);arriba.add(lateral,BorderLayout.EAST);base.add(arriba,BorderLayout.NORTH);JPanel centro=new JPanel(new BorderLayout(5,5));JPanel resumen=new JPanel(new GridLayout(2,3,8,8));resumen.setBackground(new Color(211,207,250));for(String t:new String[]{"Pago inicial","Total a financiar","Pago mensual"})resumen.add(new JLabel(t,SwingConstants.CENTER));for(JLabel l:new JLabel[]{lblPagoInicial,lblTotalFin,lblPagoMensual}){l.setHorizontalAlignment(SwingConstants.CENTER);resumen.add(l);}centro.add(resumen,BorderLayout.NORTH);JPanel tabla=new JPanel(new BorderLayout());JPanel filtro=new JPanel();filtro.add(new JLabel("Mis cotizaciones"));filtro.add(cmbStatus);tabla.add(filtro,BorderLayout.NORTH);tabla.add(new JScrollPane(tbDatos));centro.add(tabla);base.add(centro);JPanel botones=new JPanel();for(JButton b:new JButton[]{btnLimpiar,btnCancelar,btnCerrar})botones.add(b);base.add(botones,BorderLayout.SOUTH);btnNuevo.addActionListener(e->{limpiar();habilitar();txtNumCotizacion.requestFocusInWindow();});btnLimpiar.addActionListener(e->{limpiar();txtNumCotizacion.requestFocusInWindow();});btnCancelar.addActionListener(e->{limpiar();deshabilitar();});btnCerrar.addActionListener(e->cerrarVentana());spnPorcentaje.addChangeListener(e->calcular());txtPrecio.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){public void insertUpdate(javax.swing.event.DocumentEvent e){calcular();}public void removeUpdate(javax.swing.event.DocumentEvent e){calcular();}public void changedUpdate(javax.swing.event.DocumentEvent e){calcular();}});}
 public void limpiar(){txtNumCotizacion.setText("");txtDescripcion.setText("");txtPrecio.setText("");spnPorcentaje.setValue(0);rdb12.setSelected(true);jdcFecha.setDate(new java.util.Date());calcular();}
 private void controles(boolean activo){for(JComponent c:new JComponent[]{txtNumCotizacion,txtDescripcion,txtPrecio,spnPorcentaje,jdcFecha,rdb12,rdb24,rdb36,rdb48,btnLimpiar,btnCancelar})c.setEnabled(activo);btnNuevo.setEnabled(!activo);btnBuscar.setEnabled(false);btnGuardar.setEnabled(false);btnHabilitar.setEnabled(false);btnDeshabilitar.setEnabled(false);}
 public void habilitar(){controles(true);}public void deshabilitar(){controles(false);}
 public boolean validar(){try{return !txtNumCotizacion.getText().isBlank()&&!txtDescripcion.getText().isBlank()&&Float.isFinite(Float.parseFloat(txtPrecio.getText()))&&Float.parseFloat(txtPrecio.getText())>0&&jdcFecha.getDate()!=null;}catch(NumberFormatException e){return false;}}
 private int plazo(){return rdb48.isSelected()?48:rdb36.isSelected()?36:rdb24.isSelected()?24:12;}
 public Cotizacion llenarObjeto(){if(!validar())throw new IllegalArgumentException("Completa los campos obligatorios");return new Cotizacion(0,txtNumCotizacion.getText().trim(),txtDescripcion.getText().trim(),((Number)spnPorcentaje.getValue()).floatValue(),Float.parseFloat(txtPrecio.getText()),plazo(),new java.sql.Date(jdcFecha.getDate().getTime()),1);}
 public void mostrarDatos(Cotizacion c){txtNumCotizacion.setText(c.getNumCotizacion());txtDescripcion.setText(c.getDescripcion());txtPrecio.setText(String.valueOf(c.getPrecio()));spnPorcentaje.setValue((int)c.getPorcentaje());jdcFecha.setDate(c.getFecha());switch(c.getPlazo()){case 24:rdb24.setSelected(true);break;case 36:rdb36.setSelected(true);break;case 48:rdb48.setSelected(true);break;default:rdb12.setSelected(true);}calcular();}
 public void mostrarMensaje(String mensaje){JOptionPane.showMessageDialog(this,mensaje);}
 private void calcular(){float precio=0;try{precio=Float.parseFloat(txtPrecio.getText());if(!Float.isFinite(precio)||precio<0)precio=0;}catch(NumberFormatException e){}Cotizacion c=new Cotizacion();c.setPrecio(precio);c.setPorcentaje(((Number)spnPorcentaje.getValue()).floatValue());c.setPlazo(plazo());lblPagoInicial.setText(formato.format(c.calcularPagoInicial()));lblTotalFin.setText(formato.format(c.calcularTotalFin()));lblPagoMensual.setText(formato.format(c.calcularPagoMensual()));}
 private void cerrarVentana(){if(JOptionPane.showConfirmDialog(this,"¿Deseas cerrar la ventana?","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)dispose();}
}
